const http = require('https');

const options = {
  method: 'GET',
  hostname: 'www.sefaria.org',
  port: null,
  path: '/api/calendars',
  headers: {
    accept: 'application/json'
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on('data', function (chunk) {
    chunks.push(chunk);
  });

  res.on('end', function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.end();

