use reqwest;

#[tokio::main]
pub async fn main() {
    let url = "https://www.sefaria.org/api/calendars";

    let client = reqwest::Client::new();
    let response = client.get(url)
        .header("accept", "application/json")
        .send()
        .await;

    let results = response.unwrap()
        .json::<serde_json::Value>()
        .await
        .unwrap();

    println!("{}", results);
}
